// Argus /api/news returns { items: [...] }. Each item has:
//   - datePublished: ISO timestamp string (used as source_date)
//   - links: [{rel:'article', href:<api>}, {rel:..., href:<public www>}]
// links[1].href is the public www.argusmedia.com URL — that's the dedup
// key and the page content-sourcing extracts from. links[0] is the API
// endpoint (api.argusmedia.com) which we ignore.
const items = $input.all();
const HOST_ALLOWLIST = /^https:\/\/(www\.)?argusmedia\.com(\/|$)/;
const out = [];
const seen = new Set();
let droppedNoLink = 0, droppedNoDate = 0, droppedBadHost = 0, droppedDup = 0;
for (const wrap of items) {
  const news = wrap.json || {};
  const list = Array.isArray(news.items) ? news.items : [];
  for (const it of list) {
    const links = Array.isArray(it.links) ? it.links : [];
    const publicLink = links[1] && typeof links[1].href === 'string' ? links[1].href : null;
    if (!publicLink) { droppedNoLink++; continue; }
    if (!publicLink.startsWith('https://')) { droppedBadHost++; continue; }
    if (!HOST_ALLOWLIST.test(publicLink)) { droppedBadHost++; continue; }
    if (!it.datePublished) { droppedNoDate++; continue; }
    if (seen.has(publicLink)) { droppedDup++; continue; }
    seen.add(publicLink);
    out.push({ url: publicLink, source_date: String(it.datePublished) });
  }
}
return [{ json: { urls: out, urlsEmitted: out.length, droppedNoLink, droppedNoDate, droppedBadHost, droppedDup } }];

// Shape into the /research-ingest contract. urls already carries
// {url, source_date} from the extractor.
const urls = $input.first().json.urls || [];
if (!urls.length) {
  throw new Error('no_urls_extracted — upstream Argus call returned 0 publishable items');
}
if (urls.length > 100) urls.length = 100; // cap to /research-ingest max_length
return [{
  json: {
    source_type: 'Website',
    source_name: 'Argus Media',
    source_category: 'News',
    urls,
  },
}];

const r = $input.first().json;
return [{ json: {
  status: r.status || 'queued',
  queued: r.queued ?? 0,
  skipped_dedup: r.skipped_dedup ?? 0,
  source_name: 'Argus Media',
}}];

const r = $input.first().json;
const status = r.statusCode || r.status || 502;
return [{ json: {
  status: 'error',
  upstream_status: status,
  error: typeof r.error === 'string' ? r.error : (r.message || 'upstream_failed'),
  source_name: 'Argus Media',
}}];
